CREATE TABLE [companies] (
    [Id] uniqueidentifier NOT NULL,
    [Name] nvarchar(200) NOT NULL,
    [Industry] nvarchar(100) NULL,
    [BusinessType] nvarchar(100) NULL,
    [Timezone] nvarchar(100) NULL,
    [Currency] nvarchar(16) NULL,
    [Language] nvarchar(16) NULL,
    [ComplianceRegion] nvarchar(50) NULL,
    [size_band] nvarchar(32) NOT NULL DEFAULT N'unspecified',
    [branding_json] nvarchar(max) NOT NULL DEFAULT (N'{}'),
    [settings_json] nvarchar(max) NOT NULL DEFAULT (N'{}'),
    [OnboardingStateJson] nvarchar(max) NULL,
    [OnboardingCurrentStep] int NULL,
    [OnboardingTemplateId] nvarchar(100) NULL,
    [OnboardingStatus] nvarchar(32) NOT NULL DEFAULT N'not_started',
    [finance_seed_status] nvarchar(32) NOT NULL DEFAULT N'not_seeded',
    [finance_seed_status_updated_at] datetime2 NOT NULL,
    [finance_seeded_at] datetime2 NULL,
    [OnboardingLastSavedUtc] datetime2 NULL,
    [OnboardingCompletedUtc] datetime2 NULL,
    [OnboardingAbandonedUtc] datetime2 NULL,
    [CreatedUtc] datetime2 NOT NULL,
    [UpdatedUtc] datetime2 NOT NULL,
    [is_demo_tenant] bit NOT NULL DEFAULT CAST(0 AS bit),
    [demo_scenario_key] nvarchar(100) NULL,
    [demo_scenario_version] int NULL,
    CONSTRAINT [PK_companies] PRIMARY KEY ([Id]),
    CONSTRAINT [CK_companies_demo_marker] CHECK (is_demo_tenant = 0 OR (demo_scenario_key IS NOT NULL AND demo_scenario_version >= 1)),
    CONSTRAINT [CK_companies_finance_seed_status] CHECK (finance_seed_status IN ('not_seeded', 'seeding', 'seeded', 'failed'))
);
GO


