CREATE TABLE [accounting_authority_periods] (
    [id] uniqueidentifier NOT NULL,
    [company_id] uniqueidentifier NOT NULL,
    [effective_from] date NOT NULL,
    [effective_to] date NULL,
    [authority] nvarchar(32) NOT NULL,
    [target_authority] nvarchar(32) NULL,
    [provider_key] nvarchar(64) NULL,
    [change_reason] nvarchar(1000) NOT NULL,
    [opening_balances_reconciled] bit NOT NULL DEFAULT CAST(0 AS bit),
    [trial_balance_reconciled] bit NOT NULL DEFAULT CAST(0 AS bit),
    [source_mappings_reconciled] bit NOT NULL DEFAULT CAST(0 AS bit),
    [conflict_count] int NOT NULL DEFAULT 0,
    [validation_summary] nvarchar(1000) NULL,
    [changed_by_user_id] uniqueidentifier NOT NULL,
    [completed_by_user_id] uniqueidentifier NULL,
    [created_utc] datetime2 NOT NULL,
    [updated_utc] datetime2 NOT NULL,
    [completed_utc] datetime2 NULL,
    [version] bigint NOT NULL,
    CONSTRAINT [PK_accounting_authority_periods] PRIMARY KEY ([id]),
    CONSTRAINT [AK_accounting_authority_periods_company_id_id] UNIQUE ([company_id], [id]),
    CONSTRAINT [CK_accounting_authority_periods_authority] CHECK ([authority] IN ('internal_ledger', 'external_provider', 'migration')),
    CONSTRAINT [CK_accounting_authority_periods_conflicts] CHECK ([conflict_count] >= 0),
    CONSTRAINT [CK_accounting_authority_periods_dates] CHECK ([effective_to] IS NULL OR [effective_to] >= [effective_from]),
    CONSTRAINT [CK_accounting_authority_periods_target_authority] CHECK ([target_authority] IS NULL OR [target_authority] IN ('internal_ledger', 'external_provider')),
    CONSTRAINT [FK_accounting_authority_periods_companies_company_id] FOREIGN KEY ([company_id]) REFERENCES [companies] ([Id]) ON DELETE CASCADE
);
GO


CREATE TABLE [accounting_configurations] (
    [id] uniqueidentifier NOT NULL,
    [company_id] uniqueidentifier NOT NULL,
    [base_currency] nchar(3) NOT NULL,
    [fiscal_year_start_month] int NOT NULL,
    [fiscal_year_start_day] int NOT NULL,
    [authority] nvarchar(32) NOT NULL,
    [setup_state] nvarchar(32) NOT NULL,
    [policy_pack_key] nvarchar(96) NOT NULL,
    [policy_pack_version] nvarchar(32) NOT NULL,
    [policy_pack_effective_from] date NOT NULL,
    [rounding_precision] int NOT NULL,
    [rounding_mode] nvarchar(32) NOT NULL,
    [created_by_user_id] uniqueidentifier NOT NULL,
    [updated_by_user_id] uniqueidentifier NOT NULL,
    [created_utc] datetime2 NOT NULL,
    [updated_utc] datetime2 NOT NULL,
    [version] bigint NOT NULL,
    CONSTRAINT [PK_accounting_configurations] PRIMARY KEY ([id]),
    CONSTRAINT [AK_accounting_configurations_company_id_id] UNIQUE ([company_id], [id]),
    CONSTRAINT [CK_accounting_configurations_authority] CHECK ([authority] IN ('internal_ledger', 'external_provider', 'migration')),
    CONSTRAINT [CK_accounting_configurations_fiscal_year_start_day] CHECK ([fiscal_year_start_day] >= 1 AND [fiscal_year_start_day] <= 31),
    CONSTRAINT [CK_accounting_configurations_fiscal_year_start_month] CHECK ([fiscal_year_start_month] >= 1 AND [fiscal_year_start_month] <= 12),
    CONSTRAINT [CK_accounting_configurations_rounding_precision] CHECK ([rounding_precision] >= 0 AND [rounding_precision] <= 6),
    CONSTRAINT [CK_accounting_configurations_setup_state] CHECK ([setup_state] IN ('incomplete', 'ready')),
    CONSTRAINT [FK_accounting_configurations_companies_company_id] FOREIGN KEY ([company_id]) REFERENCES [companies] ([Id]) ON DELETE CASCADE
);
GO


