    CONSTRAINT [AK_simulation_event_records_company_id_id] UNIQUE ([company_id], [id]),
    CONSTRAINT [CK_simulation_event_records_cash_snapshot] CHECK (((cash_before IS NULL AND cash_delta IS NULL AND cash_after IS NULL) OR (cash_before IS NOT NULL AND cash_delta IS NOT NULL AND cash_after IS NOT NULL AND cash_after = ROUND(cash_before + cash_delta, 2)))),
    CONSTRAINT [CK_simulation_event_records_sequence_number_positive] CHECK (sequence_number > 0),
    CONSTRAINT [FK_simulation_event_records_companies_company_id] FOREIGN KEY ([company_id]) REFERENCES [companies] ([Id]) ON DELETE CASCADE,
    CONSTRAINT [FK_simulation_event_records_simulation_event_records_company_id_parent_event_id] FOREIGN KEY ([company_id], [parent_event_id]) REFERENCES [simulation_event_records] ([company_id], [id]) ON DELETE NO ACTION
);
