    [payment_reference] nvarchar(128) NULL,
    [bankgiro] nvarchar(32) NULL,
    [plusgiro] nvarchar(32) NULL,
    [iban] nvarchar(34) NULL,
    [bic] nvarchar(11) NULL,
    [confidence] decimal(5,4) NULL,
    [confidence_level] nvarchar(16) NOT NULL,
