CREATE TABLE [decision_work_origins] (
    [Id] uniqueidentifier NOT NULL,
    [CompanyId] uniqueidentifier NOT NULL,
    [TaskId] uniqueidentifier NOT NULL,
    [RequestId] uniqueidentifier NOT NULL,
    [CreatedByUserId] uniqueidentifier NOT NULL,
    [OwnerUserId] uniqueidentifier NOT NULL,
    [SourceKind] nvarchar(16) NOT NULL,
    [SourceVersionId] uniqueidentifier NOT NULL,
    [ItemKey] nvarchar(128) NOT NULL,
    [SourceVersion] int NOT NULL,
    [SourceFingerprint] nvarchar(64) NOT NULL,
    [MonthlySnapshotId] uniqueidentifier NULL,
    [QuarterReviewId] uniqueidentifier NULL,
    [AnnualPlanId] uniqueidentifier NULL,
    [ScenarioId] uniqueidentifier NULL,
    [Objective] nvarchar(200) NOT NULL,
    [AcceptanceOutcome] nvarchar(2000) NOT NULL,
    [ProposedConstraints] nvarchar(2000) NOT NULL,
    [DueUtc] datetime2 NOT NULL,
    [CreatedUtc] datetime2 NOT NULL,
    [CommandHash] nvarchar(64) NOT NULL,
    [PreviewJson] nvarchar(max) NOT NULL,
    [PreviewChecksum] nvarchar(64) NOT NULL,
    [ApprovalId] uniqueidentifier NULL,
    CONSTRAINT [PK_decision_work_origins] PRIMARY KEY ([Id]),
    CONSTRAINT [AK_decision_work_origins_CompanyId_Id] UNIQUE ([CompanyId], [Id]),
    CONSTRAINT [CK_decision_work_source] CHECK (([SourceKind] = 'month' AND [MonthlySnapshotId] = [SourceVersionId] AND [MonthlySnapshotId] IS NOT NULL AND [QuarterReviewId] IS NULL AND [AnnualPlanId] IS NULL AND [ScenarioId] IS NULL) OR ([SourceKind] = 'quarter' AND [QuarterReviewId] = [SourceVersionId] AND [QuarterReviewId] IS NOT NULL AND [MonthlySnapshotId] IS NULL AND [AnnualPlanId] IS NULL AND [ScenarioId] IS NULL) OR ([SourceKind] = 'annual' AND [AnnualPlanId] = [SourceVersionId] AND [AnnualPlanId] IS NOT NULL AND [MonthlySnapshotId] IS NULL AND [QuarterReviewId] IS NULL AND [ScenarioId] IS NULL) OR ([SourceKind] = 'scenario' AND [ScenarioId] = [SourceVersionId] AND [ScenarioId] IS NOT NULL AND [MonthlySnapshotId] IS NULL AND [QuarterReviewId] IS NULL AND [AnnualPlanId] IS NULL)),
    CONSTRAINT [FK_decision_work_origins_annual_plan_versions_CompanyId_AnnualPlanId] FOREIGN KEY ([CompanyId], [AnnualPlanId]) REFERENCES [annual_plan_versions] ([CompanyId], [Id]),
    CONSTRAINT [FK_decision_work_origins_companies_CompanyId] FOREIGN KEY ([CompanyId]) REFERENCES [companies] ([Id]) ON DELETE CASCADE,
    CONSTRAINT [FK_decision_work_origins_monthly_review_snapshots_CompanyId_MonthlySnapshotId] FOREIGN KEY ([CompanyId], [MonthlySnapshotId]) REFERENCES [monthly_review_snapshots] ([CompanyId], [Id]),
    CONSTRAINT [FK_decision_work_origins_quarterly_reviews_CompanyId_QuarterReviewId] FOREIGN KEY ([CompanyId], [QuarterReviewId]) REFERENCES [quarterly_reviews] ([CompanyId], [Id]),
    CONSTRAINT [FK_decision_work_origins_strategic_scenario_versions_CompanyId_ScenarioId] FOREIGN KEY ([CompanyId], [ScenarioId]) REFERENCES [strategic_scenario_versions] ([CompanyId], [Id]),
    CONSTRAINT [FK_decision_work_origins_tasks_CompanyId_TaskId] FOREIGN KEY ([CompanyId], [TaskId]) REFERENCES [tasks] ([company_id], [id]),
    CONSTRAINT [FK_decision_work_origins_users_OwnerUserId] FOREIGN KEY ([OwnerUserId]) REFERENCES [users] ([Id])
);
GO


