    CONSTRAINT [FK_sales_presentation_runs_customer_companies_company_id_context_customer_company_id] FOREIGN KEY ([company_id], [context_customer_company_id]) REFERENCES [customer_companies] ([company_id], [id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_sales_presentation_runs_deals_company_id_context_deal_id] FOREIGN KEY ([company_id], [context_deal_id]) REFERENCES [deals] ([company_id], [id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_sales_presentation_runs_leads_company_id_context_lead_id] FOREIGN KEY ([company_id], [context_lead_id]) REFERENCES [leads] ([company_id], [id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_sales_presentation_runs_sales_meeting_sessions_company_id_meeting_session_id] FOREIGN KEY ([company_id], [meeting_session_id]) REFERENCES [sales_meeting_sessions] ([company_id], [id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_sales_presentation_runs_sales_presentation_preset_versions_company_id_preset_version_id] FOREIGN KEY ([company_id], [preset_version_id]) REFERENCES [sales_presentation_preset_versions] ([company_id], [id]) ON DELETE NO ACTION
);
