CREATE TABLE [sales_presentation_run_artifacts] (
    [id] uniqueidentifier NOT NULL,
    [company_id] uniqueidentifier NOT NULL,
    [run_id] uniqueidentifier NOT NULL,
    [preparation_version] int NOT NULL,
    [artifact_type] nvarchar(32) NOT NULL,
    [content] nvarchar(4000) NOT NULL,
    [classification] nvarchar(32) NOT NULL,
    [source_reference] nvarchar(500) NULL,
    [preset_slide_id] uniqueidentifier NULL,
    [artifact_order] int NOT NULL,
    [ai_run_id] uniqueidentifier NULL,
    [created_at] datetime2 NOT NULL,
    CONSTRAINT [PK_sales_presentation_run_artifacts] PRIMARY KEY ([id]),
    CONSTRAINT [CK_sales_presentation_run_artifacts_order] CHECK (preparation_version >= 1 AND artifact_order >= 0),
    CONSTRAINT [FK_sales_presentation_run_artifacts_sales_presentation_preset_slides_company_id_preset_slide_id] FOREIGN KEY ([company_id], [preset_slide_id]) REFERENCES [sales_presentation_preset_slides] ([company_id], [id]) ON DELETE NO ACTION,
    CONSTRAINT [FK_sales_presentation_run_artifacts_sales_presentation_runs_company_id_run_id] FOREIGN KEY ([company_id], [run_id]) REFERENCES [sales_presentation_runs] ([company_id], [id]) ON DELETE NO ACTION
);
GO


